SELECT * FROM [REPAIR_AGR_20261028].Estado;
SELECT 'CFDI_COBRANZA' Tabla,CASE WHEN EXISTS(SELECT H,COUNT_BIG(*) N FROM (SELECT HASHBYTES('SHA2_256',(SELECT T.* FOR JSON PATH,INCLUDE_NULL_VALUES,WITHOUT_ARRAY_WRAPPER)) H FROM T3.[CFDI_COBRANZA] T WHERE ASIGNACION_ID IN ('262201997234','262201997964','262201997720','262201997198')) L GROUP BY H EXCEPT SELECT H,COUNT_BIG(*) N FROM (SELECT HASHBYTES('SHA2_256',(SELECT T.* FOR JSON PATH,INCLUDE_NULL_VALUES,WITHOUT_ARRAY_WRAPPER)) H FROM [REPAIR_AGR_20261028].[Origen_CFDI_COBRANZA] T WHERE 1=1) R GROUP BY H) OR EXISTS(SELECT H,COUNT_BIG(*) N FROM (SELECT HASHBYTES('SHA2_256',(SELECT T.* FOR JSON PATH,INCLUDE_NULL_VALUES,WITHOUT_ARRAY_WRAPPER)) H FROM [REPAIR_AGR_20261028].[Origen_CFDI_COBRANZA] T WHERE 1=1) R GROUP BY H EXCEPT SELECT H,COUNT_BIG(*) N FROM (SELECT HASHBYTES('SHA2_256',(SELECT T.* FOR JSON PATH,INCLUDE_NULL_VALUES,WITHOUT_ARRAY_WRAPPER)) H FROM T3.[CFDI_COBRANZA] T WHERE ASIGNACION_ID IN ('262201997234','262201997964','262201997720','262201997198')) L GROUP BY H) THEN 'DIFERENCIAS' ELSE 'IGUAL A ORIGEN' END Resultado;
