SELECT ASIGNACION_ID,NOTA_VENTA,UUID_VENTA,STATUS,FECHA_ENVIO FROM T3.CFDI_COBRANZA WHERE ASIGNACION_ID IN ('262201997234','262201997964','262201997720','262201997198');
